<script setup>import {computed,ref} from 'vue';import {useApp} from '../stores/app';import {money} from '../services/storage';import PageTitle from '../components/PageTitle.vue';const s=useApp(),date=ref('');const rows=computed(()=>s.data.orders.filter(o=>!date.value||o.date===date.value));const total=computed(()=>rows.value.filter(o=>o.status!=='Batal').reduce((a,o)=>a+o.total,0));function exportCsv(){const csv=['Tanggal,Antrean,Metode,Status,Total',...rows.value.map(o=>[o.date,o.queue,o.method,o.status,o.total].join(','))].join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download='laporan-sruput.csv';a.click();URL.revokeObjectURL(url)}</script><template><PageTitle title="Laporan penjualan" subtitle="Rekap transaksi yang tersimpan di perangkat ini."/><div class="actions"><input type="date" v-model="date"><button @click="exportCsv">Unduh CSV</button></div><h2>{{money(total)}}</h2><div class="table-wrap card"><table><thead><tr><th>Tanggal</th><th>Antrean</th><th>Status</th><th>Metode</th><th>Total</th></tr></thead><tbody><tr v-for="o in rows" :key="o.id"><td>{{o.date}}</td><td>{{o.queue}}</td><td>{{o.status}}</td><td>{{o.method}}</td><td>{{money(o.total)}}</td></tr></tbody></table><p v-if="!rows.length">Belum ada transaksi.</p></div></template>
